input.command:
python3 -c "
import json
d=json.load(open('results.json'))
K={'k^2+1':0.138082643,'k^3+2':0.135607536,'2k+1':0.142613326}
for p,v in d['polynomials'].items():
  ce=v['constant_extrapolated']; print('==',p,'extrap',ce['value'],'+-',ce['uncertainty'],'pred',K[p], 'joint',v['fit_joint'])
  xs=sorted(set(r['x'] for r in v['rows']))
  for r in v['rows']+v['diagnostic_rows']:
    if r['x'] in (xs[-1],xs[-2]) :
      rr=r['ratio_actual']; N=r['normalised']
      print(r['x'],r['y'],round(rr,4),round(N,5),' (N-pred)/sqrt(r)=',round((N-K[p])/rr**0.5,4))
"

